sp_widget.client_script:
api.controller = function ($scope, $location, $window) {
  /* widget controller */
  var c = this;

  // Function to programmatically click the "Discard" button
  function clickDiscardButton() {
    var discardButton = document.querySelector(
      'button[ng-click="buttonClicked(button)"]:not(.btn-primary)'
    );
    if (discardButton) {
      //console.log("Discard button clicked automatically.");
      discardButton.click(); // Programmatically click the Discard button
    } else {
     // console.warn("Discard button not found.");
    }
  }

  // Redirect function for navigation with discard action
  $scope.redirectToExit = function () {
    console.log("Performing discard action before redirect.");
    // Ensure the discard action is triggered

    var newUrl = $location.absUrl().split('?')[0] + '?id=' + c.data.href;
   // console.log("Redirecting to:", newUrl);

    $window.location.href = newUrl;
		clickDiscardButton();
  };

  // Handle back navigation (popstate event)
  window.addEventListener("popstate", function () {
   // console.log("Back button pressed.");
    clickDiscardButton();
  });

  // Cleanup event listener when the widget is destroyed
  $scope.$on("$destroy", function () {
    window.removeEventListener("popstate", clickDiscardButton);
  });


  // Set the heading dynamically from data
  $scope.heading = $scope.data.heading;
};

sp_widget.css:
.widget-title {
  font-family: 'Arial', sans-serif;
  font-size: 24px;
  font-weight: bold;
  color: #03428E;
  background-color: #f9f9f9;
  padding: 20px;
  border-radius: 10px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  display: flex;
  align-items: center;
  justify-content: space-between;
  transition: background-color 0.3s ease;
  margin-bottom : 2rem;
}

.widget-title:hover {
  background-color: #e9e9e9;
}

.widget-title i {
  font-size: 24px;
  cursor: pointer;
}

.widget-title .exit-icon {
  margin-right: 10px;
}

.widget-title .content {
  flex-grow: 1; /* This ensures the content takes up available space */
  display: flex;
  justify-content: center; /* Centers the heading */
}

.widget-title .chart-icon {
  margin-left: 10px;
}

